/**
 * Seed SonicJS employee-directory D1 database directly via SQL (50,000 employees).
 *
 * Reads employees-seed.json (generated by sonicjs-payload-demo/seed/generate.ts)
 * and bulk-inserts departments, regions, and employees into the SonicJS documents
 * table using `wrangler d1 execute --remote`.
 *
 * Both this script and seed/seed-payload.ts (in sonicjs-payload-demo) consume the
 * SAME JSON file, ensuring identical data on both sides of the speed comparison.
 *
 * Usage:
 *   # 1. Generate seed data (from sonicjs-payload-demo repo):
 *   #    npx tsx seed/generate.ts
 *   #    → writes sonicjs-payload-demo/seed/employees-seed.json
 *
 *   # 2. Run this seeder (point SEED_FILE at the generated JSON):
 *   SEED_FILE=../sonicjs-payload-demo/seed/employees-seed.json \
 *     npx tsx my-sonicjs-app/scripts/seed-employees-50k.ts
 *
 *   # Or generate inline (no JSON file needed — same PRNG, same output):
 *   npx tsx my-sonicjs-app/scripts/seed-employees-50k.ts --inline
 *
 *   # Dry-run: generate SQL without executing
 *   npx tsx my-sonicjs-app/scripts/seed-employees-50k.ts --dry-run
 *
 * SonicJS documents schema (from my-sonicjs-app/migrations/0002_documents.sql):
 *   Each document is a single row with is_current_draft=1, is_published=1, status='published'.
 *   Employees reference dept/region by root_id (e.g. 'dept-engineering', 'region-us-east').
 */

import fs from 'fs'
import path from 'path'
import { execSync } from 'child_process'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const DRY_RUN = process.argv.includes('--dry-run')
const INLINE = process.argv.includes('--inline')

// D1 database name as configured in wrangler.client-backend.toml
const DB_NAME = 'sonicjs-demo'
const WRANGLER_CONFIG = 'wrangler.client-backend.toml'

const ROWS_PER_INSERT = 500
const EMPLOYEES_PER_CHUNK = 5_000
const TENANT = 'default'
const NOW_UNIX = `unixepoch()`

// ── Seed constants (must match sonicjs-payload-demo/seed/generate.ts exactly) ──

const DEPARTMENTS = [
  { slug: 'engineering', name: 'Engineering',  description: 'Builds and maintains the product',             icon: '🔧', color: '#3B82F6' },
  { slug: 'product',     name: 'Product',      description: 'Drives product vision and roadmap',            icon: '📊', color: '#8B5CF6' },
  { slug: 'design',      name: 'Design',       description: 'Shapes user experience and visual identity',   icon: '🎨', color: '#EC4899' },
  { slug: 'marketing',   name: 'Marketing',    description: 'Grows brand awareness and demand',             icon: '📣', color: '#F59E0B' },
  { slug: 'sales',       name: 'Sales',        description: 'Closes deals and grows revenue',               icon: '💼', color: '#10B981' },
  { slug: 'hr',          name: 'HR',           description: 'Grows and supports the team',                  icon: '🤝', color: '#06B6D4' },
  { slug: 'finance',     name: 'Finance',      description: 'Manages financial health and planning',        icon: '💰', color: '#84CC16' },
  { slug: 'legal',       name: 'Legal',        description: 'Protects the business and ensures compliance', icon: '⚖️', color: '#6366F1' },
  { slug: 'operations',  name: 'Operations',   description: 'Keeps the business running smoothly',         icon: '⚙️', color: '#F97316' },
]

const REGIONS = [
  { slug: 'us-east',  name: 'US-East',  display_name: 'US East Coast',   timezone: 'America/New_York',    flag_emoji: '🇺🇸' },
  { slug: 'us-west',  name: 'US-West',  display_name: 'US West Coast',   timezone: 'America/Los_Angeles', flag_emoji: '🇺🇸' },
  { slug: 'eu-west',  name: 'EU-West',  display_name: 'Western Europe',  timezone: 'Europe/London',       flag_emoji: '🇪🇺' },
  { slug: 'eu-north', name: 'EU-North', display_name: 'Northern Europe', timezone: 'Europe/Stockholm',    flag_emoji: '🇸🇪' },
  { slug: 'apac',     name: 'APAC',     display_name: 'Asia Pacific',    timezone: 'Asia/Singapore',      flag_emoji: '🌏' },
  { slug: 'latam',    name: 'LATAM',    display_name: 'Latin America',   timezone: 'America/Sao_Paulo',   flag_emoji: '🌎' },
]

const TITLES_BY_DEPT: Record<string, string[]> = {
  engineering: ['Software Engineer','Senior Engineer','Staff Engineer','Engineering Manager','DevOps Engineer','Frontend Engineer','Platform Engineer','Security Engineer'],
  product:     ['Product Manager','Senior PM','Director of Product','Product Analyst','Associate PM','Group PM'],
  design:      ['UX Designer','Product Designer','Design Lead','Visual Designer','UX Researcher','Design Systems Engineer'],
  marketing:   ['Marketing Manager','Content Strategist','Growth Manager','Brand Designer','SEO Specialist','Demand Gen Manager'],
  sales:       ['Account Executive','Sales Manager','SDR','VP of Sales','Customer Success Manager','Enterprise AE'],
  hr:          ['HR Manager','Recruiter','People Ops','HR Business Partner','Talent Lead','Comp & Benefits Analyst'],
  finance:     ['Finance Manager','Financial Analyst','Controller','CFO','Accountant','FP&A Analyst'],
  legal:       ['Legal Counsel','General Counsel','Compliance Manager','Legal Ops','Privacy Counsel'],
  operations:  ['Operations Manager','Chief of Staff','Program Manager','IT Manager','Facilities Manager','Ops Analyst'],
}

const FIRST = [
  'Alex','Jordan','Morgan','Taylor','Casey','Riley','Avery','Drew','Blake','Cameron',
  'Quinn','Peyton','Skyler','Reese','Logan','Parker','Hayden','Sydney','Jamie','Devon',
  'Emma','Liam','Olivia','Noah','Ava','Elijah','Sophia','Lucas','Isabella','Mason',
  'Charlotte','Ethan','Amelia','Aiden','Mia','James','Harper','Sebastian','Evelyn','Michael',
  'Priya','Kai','Zara','Noa','Ravi','Sasha','Mika','Ling','Jin','Aria',
  'Felix','Luna','Omar','Isla','Marco','Yuki','Diego','Freya','Kofi','Mei',
]

const LAST = [
  'Smith','Johnson','Williams','Brown','Jones','Garcia','Miller','Davis','Wilson','Moore',
  'Taylor','Anderson','Thomas','Jackson','White','Harris','Martin','Thompson','Young','Lewis',
  'Walker','Hall','Allen','King','Wright','Scott','Torres','Nguyen','Hill','Flores',
  'Green','Adams','Nelson','Baker','Carter','Mitchell','Perez','Roberts','Turner','Phillips',
  'Patel','Kumar','Chen','Zhang','Kim','Park','Nakamura','Santos','Silva','Müller',
  'Osei','Tanaka','Costa','Rossi','Dubois','Ahmed','Hassan','Johansson','Weber','Ferreira',
]

function seededRand(seed: number) {
  let s = seed
  return () => { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646 }
}
function pick<T>(arr: T[], rand: () => number): T {
  return arr[Math.floor(rand() * arr.length)]!
}
function normalize(s: string): string {
  return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '')
}
function generateInline(count: number) {
  const rand = seededRand(42)
  const deptSlugs = DEPARTMENTS.map(d => d.slug)
  const regionSlugs = REGIONS.map(r => r.slug)
  return Array.from({ length: count }, (_, i) => {
    const deptSlug = pick(deptSlugs, rand)
    const regionSlug = pick(regionSlugs, rand)
    const firstName = pick(FIRST, rand)
    const lastName = pick(LAST, rand)
    return {
      index: i + 1,
      first_name: firstName, last_name: lastName,
      department_slug: deptSlug, region_slug: regionSlug,
      job_title: pick(TITLES_BY_DEPT[deptSlug]!, rand),
      email: `${normalize(firstName)}.${normalize(lastName)}${i + 1}@example.com`,
      phone: `+1-555-${String(i + 1).padStart(5, '0')}`,
      avatar_seed: `employee-${i + 1}-${firstName}-${lastName}`,
    }
  })
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function esc(s: string | number) { return String(s).replace(/'/g, "''") }
function jsonEsc(obj: unknown) { return esc(JSON.stringify(obj)) }

function deptId(slug: string) { return `dept-${slug}` }
function regionId(slug: string) { return `region-${slug}` }

function runSqlFile(filePath: string, label: string) {
  if (DRY_RUN) {
    console.log(`  [dry-run] wrangler d1 execute ${DB_NAME} --remote --config=${WRANGLER_CONFIG} --file=${path.basename(filePath)}`)
    return
  }
  console.log(`  Executing ${label}…`)
  execSync(
    `npx wrangler d1 execute ${DB_NAME} --remote --config="${WRANGLER_CONFIG}" --file="${filePath}"`,
    { stdio: 'inherit', cwd: path.join(__dirname, '..') },
  )
}

// ── SQL builders ──────────────────────────────────────────────────────────────

function buildDeptRegionSql(): string {
  const lines = [
    '-- SonicJS seed: document_types + departments + regions',
    'PRAGMA foreign_keys=OFF;',
    '',
    '-- Wipe existing employees, departments, regions',
    `DELETE FROM documents WHERE type_id IN ('employees','departments','regions') AND tenant_id='${TENANT}';`,
    '',
    '-- Ensure document_types exist for departments, regions, employees',
  ]

  const now = Math.floor(Date.now() / 1000)
  const defaultGrants = JSON.stringify({ admin: ['read','create','update','delete','publish','manage'], editor: ['read','create','update','publish'], viewer: ['read'], public: ['read'] })
  const emptySchema = JSON.stringify({ queryableFields: [], settings: {} })
  const settings = JSON.stringify({ baseGrants: JSON.parse(defaultGrants), maxVersionsPerRoot: 50 })

  for (const [id, displayName, description] of [
    ['departments', 'Departments', 'Company departments'],
    ['regions', 'Regions', 'Geographic regions'],
    ['employees', 'Employees', 'Employee directory — 50k speed demo'],
  ] as [string, string, string][]) {
    lines.push(
      `INSERT OR IGNORE INTO document_types (id, name, display_name, description, schema, queryable_fields, settings, source, schema_version, is_system, is_active, is_auth, created_at, updated_at) ` +
      `VALUES ('${id}', '${id}', '${displayName}', '${description}', '${esc(emptySchema)}', '[]', '${esc(settings)}', 'system', 1, 0, 1, 0, ${now}, ${now});`,
    )
  }

  lines.push('', '-- Departments')
  for (const d of DEPARTMENTS) {
    const id = deptId(d.slug)
    const data = jsonEsc({ title: d.name, slug: d.slug, status: 'published', name: d.name, description: d.description, icon: d.icon, color: d.color })
    lines.push(
      `INSERT INTO documents (id, root_id, type_id, type_version, version_number, is_current_draft, is_published, status, ` +
      `slug, title, tenant_id, locale, translation_group_id, parent_root_id, sort_order, visible, published_at, data, metadata, created_at, updated_at) VALUES ` +
      `('${id}', '${id}', 'departments', 1, 1, 1, 1, 'published', '${d.slug}', '${esc(d.name)}', '${TENANT}', 'default', '', '', 0, 1, ${NOW_UNIX}, '${data}', '{}', ${NOW_UNIX}, ${NOW_UNIX});`,
    )
  }

  lines.push('', '-- Regions')
  for (const r of REGIONS) {
    const id = regionId(r.slug)
    const data = jsonEsc({ title: r.display_name, slug: r.slug, status: 'published', name: r.name, display_name: r.display_name, timezone: r.timezone, flag_emoji: r.flag_emoji })
    lines.push(
      `INSERT INTO documents (id, root_id, type_id, type_version, version_number, is_current_draft, is_published, status, ` +
      `slug, title, tenant_id, locale, translation_group_id, parent_root_id, sort_order, visible, published_at, data, metadata, created_at, updated_at) VALUES ` +
      `('${id}', '${id}', 'regions', 1, 1, 1, 1, 'published', '${r.slug}', '${esc(r.display_name)}', '${TENANT}', 'default', '', '', 0, 1, ${NOW_UNIX}, '${data}', '{}', ${NOW_UNIX}, ${NOW_UNIX});`,
    )
  }

  lines.push('', 'PRAGMA foreign_keys=ON;')
  return lines.join('\n')
}

type EmpRecord = { index: number; first_name: string; last_name: string; department_slug: string; region_slug: string; job_title: string; email: string; phone: string; avatar_seed: string }

function buildEmployeeChunkSql(chunk: EmpRecord[], chunkNum: number, totalChunks: number): string {
  const lines = [
    `-- SonicJS seed: employees chunk ${chunkNum}/${totalChunks} (#${chunk[0]!.index}–#${chunk[chunk.length-1]!.index})`,
    'PRAGMA foreign_keys=OFF;',
    '',
  ]

  for (let i = 0; i < chunk.length; i += ROWS_PER_INSERT) {
    const batch = chunk.slice(i, i + ROWS_PER_INSERT)
    const vals = batch.map(emp => {
      const id = `emp-${emp.index}`
      const dId = deptId(emp.department_slug)
      const rId = regionId(emp.region_slug)
      const fullName = `${emp.first_name} ${emp.last_name}`
      const slug = `${normalize(emp.first_name)}-${normalize(emp.last_name)}-${emp.index}`
      const data = jsonEsc({
        title: fullName, slug, status: 'published',
        first_name: emp.first_name, last_name: emp.last_name,
        department: dId, region: rId,
        job_title: emp.job_title,
        email: emp.email, phone: emp.phone,
        avatar_seed: emp.avatar_seed,
      })
      return (
        `('${id}', '${id}', 'employees', 1, 1, 1, 1, 'published', '${esc(slug)}', '${esc(fullName)}', '${TENANT}', 'default', '', '', ${emp.index}, 1, ${NOW_UNIX}, '${data}', '{}', ${NOW_UNIX}, ${NOW_UNIX})`
      )
    })
    lines.push(
      'INSERT INTO documents (id, root_id, type_id, type_version, version_number, is_current_draft, is_published, status, slug, title, tenant_id, locale, translation_group_id, parent_root_id, sort_order, visible, published_at, data, metadata, created_at, updated_at) VALUES',
    )
    lines.push(vals.join(',\n') + ';')
    lines.push('')
  }

  lines.push('PRAGMA foreign_keys=ON;')
  return lines.join('\n')
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  let employees: EmpRecord[]

  if (INLINE) {
    console.log('Generating 50,000 employees inline (PRNG seed=42)…')
    employees = generateInline(50_000) as EmpRecord[]
  } else {
    const seedEnv = process.env['SEED_FILE']
    const seedPath = seedEnv
      ? path.resolve(seedEnv)
      : path.join(__dirname, '../../sonicjs-payload-demo/seed/employees-seed.json')

    if (!fs.existsSync(seedPath)) {
      console.error(`❌ Seed file not found: ${seedPath}`)
      console.error('   Either run with --inline, or set SEED_FILE=/path/to/employees-seed.json')
      process.exit(1)
    }
    console.log(`Loading seed data from ${seedPath}…`)
    ;({ employees } = JSON.parse(fs.readFileSync(seedPath, 'utf8')))
  }

  const tmpDir = path.join(__dirname, '../../.tmp-seed')
  fs.mkdirSync(tmpDir, { recursive: true })

  try {
    console.log('\n[1/2] Seeding document_types, departments & regions…')
    const deptFile = path.join(tmpDir, 'sonic-seed-depts-regions.sql')
    fs.writeFileSync(deptFile, buildDeptRegionSql())
    runSqlFile(deptFile, 'document_types + departments + regions')

    const totalChunks = Math.ceil(employees.length / EMPLOYEES_PER_CHUNK)
    console.log(`\n[2/2] Seeding ${employees.length.toLocaleString()} employees in ${totalChunks} chunks…`)
    for (let c = 0; c < totalChunks; c++) {
      const chunk = employees.slice(c * EMPLOYEES_PER_CHUNK, (c + 1) * EMPLOYEES_PER_CHUNK) as EmpRecord[]
      const sql = buildEmployeeChunkSql(chunk, c + 1, totalChunks)
      const chunkFile = path.join(tmpDir, `sonic-seed-employees-${String(c + 1).padStart(2, '0')}.sql`)
      fs.writeFileSync(chunkFile, sql)
      runSqlFile(chunkFile, `employees chunk ${c + 1}/${totalChunks} (#${chunk[0]!.index}–#${chunk[chunk.length-1]!.index})`)
    }

    console.log('\n✓ SonicJS D1 seed complete.')
    console.log(`  ${DEPARTMENTS.length} departments, ${REGIONS.length} regions, ${employees.length.toLocaleString()} employees`)
  } finally {
    fs.rmSync(tmpDir, { recursive: true, force: true })
  }
}

main().catch(e => { console.error(e); process.exit(1) })
